def score(y,points,cameras,gain):
 adjusted=y-gain[cameras];count=np.bincount(points,minlength=int(points.max())+1);mean=np.bincount(points,weights=adjusted,minlength=len(count))/np.maximum(count,1);e=(adjusted-mean[points])/np.log(2)
