 good=np.isfinite(rgb).all(1)&(rgb.min(1)>.002)&(rgb.max(1)<5)&(uv.min(1)>=4)&(uv[:,0]<=1916)&(uv[:,1]<=1008)&(contrast<.5);counts=np.bincount(points[good],minlength=points.max()+1);good&=counts[points]>=3;p=points[good];c=cameras[good];base=np.log(rgb[good]@np.array([.2126,.7152,.0722]));unique=np.unique(p);group=np.zeros(p.max()+1,int);group[np.random.default_rng(20261105).permutation(unique)]=np.arange(len(unique))%5;old=json.loads((P/'independent_scalar_review.json').read_text());assert len(p)==old['observations'] and len(unique)==old['tracks'];oldEV={q['camera']:q['scalar_correction_EV']for q in old['camera_rows']};radial4=2*np.log2(1+r2[good]);center=float(radial4.mean());results={};fitexports={};floorids=np.array([237,238,239,240,242,243,253,263,3738,3739,3800,4246,4766,8290]);floor=np.isin(p,floorids)
